/**
 * main.js — self-contained Three.js anatomical oesophagus scene.
 *
 * No backend. Assets consumed (all generated by tools/, all with provenance):
 *   assets/esophagus.glb              8 real segmentation surfaces, subject s0688
 *   assets/esophagus_centreline.json  measured centreline + inscribed-radius profile
 *   assets/esophagus_vessels.json     7 CCO trees + the palisade-zone network
 *   assets/esophagus_flow.json        baked flow paths, v = Q/A per sample
 *   assets/esophagus_model.json       wall, muscle transition, sphincters, peristalsis
 *   assets/esophagus_expression.json  measured single-cell ADME panel
 *   assets/geometry_report.json       measured-vs-reference table (shown in-scene)
 *
 * Five views:
 *   organ      the oesophagus in situ with trachea, aorta, vertebrae, stomach
 *   vessels    the four arterial territories, three venous territories and the
 *              porto-systemic palisade zone
 *   section    the muscle-type transition along the long axis + the four-layer
 *              wall wedge at 60x
 *   micro      the stratified squamous epithelium at 600x
 *   molecular  the measured ADME panel on the squamous stack
 *
 * Public API (also used by the automated probe):
 *   const api = await createEsophagusScene({ container, assetBase, view })
 *   api.setView(...), api.setPlaybackRate(x), api.swallow(), api.secondary(s),
 *   api.setTreeVisible(name, on), api.setReflux(on), api.setVarices(on),
 *   api.measureWave(), api.dispose()
 *   window.__eso3d  diagnostics for the headless benchmark
 */

import * as THREE from 'three';
import { GLTFLoader } from '../vendor/jsm/loaders/GLTFLoader.js';
import { OrbitControls } from '../vendor/jsm/controls/OrbitControls.js';
import { RoomEnvironment } from '../vendor/jsm/environments/RoomEnvironment.js';

import { buildLumen, makeLumenMaterial, Wave, WAVE } from './peristalsis.js';
import { buildVesselMesh, buildPalisadeMesh, makeVesselMaterial, TREE_COLOR, TREE_LABEL } from './vessels.js';
import { FlowSystem } from './flow.js';
import { buildWallWedge, buildEpithelium, WALL_MAG, EPI_MAG, wallThicknessMm } from './wall.js';
import { buildMolecular, resolveStrata, LOCALISED, PILL_OESOPHAGITIS } from './molecular.js';
import { HUD, NARROW_PX } from './hud.js';

const SECTION_OFFSET = new THREE.Vector3(620, 0, 0);
const MICRO_OFFSET = new THREE.Vector3(0, -1500, 0);
const MOL_OFFSET = new THREE.Vector3(0, -2600, 0);

const ARTERIES = ['A1_inferior_thyroid_artery', 'A2_bronchial_artery',
  'A3_aortic_oesophageal_branches', 'A4_left_gastric_ascending'];
const VEINS = ['V1_inferior_thyroid_vein_systemic', 'V2_azygos_systemic', 'V3_left_gastric_portal'];

export async function createEsophagusScene (opts = {}) {
  const container = opts.container || document.body;
  const base = opts.assetBase || './assets/';
  const stage = (s) => { window.__eso3dStage = s; };

  stage('renderer:begin');
  const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
  const narrow0 = container.clientWidth < NARROW_PX;
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, narrow0 ? 1.75 : 2));
  renderer.setSize(container.clientWidth, container.clientHeight);
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.04;
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  container.appendChild(renderer.domElement);
  renderer.domElement.style.display = 'block';

  const hudCanvas = document.createElement('canvas');
  hudCanvas.style.cssText = 'position:absolute;inset:0;pointer-events:none';
  container.appendChild(hudCanvas);
  const hud = new HUD(hudCanvas);

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x070a10);
  const pmrem = new THREE.PMREMGenerator(renderer);
  scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
  scene.add(new THREE.HemisphereLight(0xcfe0ff, 0x241a18, 0.9));
  const key = new THREE.DirectionalLight(0xffffff, 1.5); key.position.set(260, 420, 520); scene.add(key);
  const rim = new THREE.DirectionalLight(0x9fc0ff, 0.6); rim.position.set(-380, 120, -360); scene.add(rim);

  const camera = new THREE.PerspectiveCamera(42, Math.max(1e-3, container.clientWidth / container.clientHeight), 1, 12000);
  const controls = new OrbitControls(camera, renderer.domElement);
  controls.enableDamping = true; controls.dampingFactor = 0.08;

  stage('assets:fetch');
  const J = async (f) => (await fetch(base + f)).json();
  const [cl, ves, flowSpec, model, geo] = await Promise.all([
    J('esophagus_centreline.json'), J('esophagus_vessels.json'), J('esophagus_flow.json'),
    J('esophagus_model.json'), J('geometry_report.json')
  ]);
  let expr = null, exprErr = null;
  try { expr = await J('esophagus_expression.json'); } catch (e) { exprErr = String(e); }

  // ---- centre the whole scene on the oesophagus centroid, in scene mm
  const P = cl.points_scene_mm;
  const ctr = new THREE.Vector3();
  for (const p of P) ctr.add(new THREE.Vector3(p[0], p[1], p[2]));
  ctr.divideScalar(P.length);
  const root = new THREE.Group(); root.position.copy(ctr).negate(); scene.add(root);

  stage('glb:load');
  const gltf = await new GLTFLoader().loadAsync(base + 'esophagus.glb');
  const surfaces = {};
  gltf.scene.traverse((o) => { if (o.isMesh) surfaces[o.name] = o; });
  const organGroup = new THREE.Group();
  organGroup.add(gltf.scene);
  root.add(organGroup);

  stage('lumen:build');
  const lumen = buildLumen(cl, { stride: 2 });
  const lumenMat = makeLumenMaterial({ L: lumen.L });
  const lumenMesh = new THREE.Mesh(lumen.geometry, lumenMat);
  lumenMesh.name = 'lumen';
  root.add(lumenMesh);
  // the segmentation surface and the swept lumen are the same organ; showing both
  // at once double-draws it, so the GLB oesophagus is hidden whenever the
  // animated lumen is on and the HUD says which one you are looking at
  if (surfaces.esophagus) surfaces.esophagus.visible = false;

  const uesArc = (model.sphincters[0] && model.sphincters[0].arc_mm) || 12.0;
  const lesArc = (model.sphincters[1] && model.sphincters[1].arc_mm) || 248.4;
  const wave = new Wave(lumen.L, { uesArc, lesArc });

  stage('vessels:build');
  const vesselGroups = {}; let vesselTris = 0;
  for (const name of Object.keys(ves.trees)) {
    const t = ves.trees[name];
    const built = buildVesselMesh(t);
    vesselTris += built.triangles;
    const mesh = new THREE.Mesh(built.geometry, makeVesselMaterial(TREE_COLOR[name]));
    mesh.name = 'tree_' + name;
    const g = new THREE.Group(); g.add(mesh); g.name = name;
    vesselGroups[name] = g; root.add(g);
  }
  const pzNormal = buildPalisadeMesh(ves.palisade_zone, ves.palisade_zone.normal_diameter_mm);
  const pzVarix = buildPalisadeMesh(ves.palisade_zone, ves.palisade_zone.varix_demo_diameter_mm);
  vesselTris += pzNormal.triangles;
  const pzNormalMesh = new THREE.Mesh(pzNormal.geometry, makeVesselMaterial(TREE_COLOR.PZ_palisade_normal));
  const pzVarixMesh = new THREE.Mesh(pzVarix.geometry, makeVesselMaterial(TREE_COLOR.PZ_palisade_varix, { emissive: 0.3 }));
  pzNormalMesh.name = 'palisade_normal'; pzVarixMesh.name = 'palisade_varix';
  pzVarixMesh.visible = false;
  root.add(pzNormalMesh); root.add(pzVarixMesh);

  stage('flow:build');
  const flow = new FlowSystem(flowSpec, narrow0 ? 120 : 260);
  root.add(flow.points);

  stage('section:build');
  // the wall wedge sits beside the organ, at the station of the deepest measured
  // radius minimum so the number in the HUD is a real one from this subject
  const stationIdx = (() => {
    let bi = 0, bv = 1e9;
    cl.inscribed_radius_mm.forEach((r, i) => { if (r < bv && i > 20 && i < cl.arc_mm.length - 20) { bv = r; bi = i; } });
    return bi;
  })();
  const wallGroup = buildWallWedge(cl.inscribed_radius_mm[stationIdx], { mag: WALL_MAG });
  wallGroup.position.copy(SECTION_OFFSET);
  wallGroup.visible = false; root.add(wallGroup);

  stage('micro:build');
  const epi = buildEpithelium({ mag: EPI_MAG, totalUm: 400 });
  epi.position.copy(MICRO_OFFSET); epi.visible = false; root.add(epi);

  stage('molecular:build');
  const mol = buildMolecular(expr, { mag: EPI_MAG });
  mol.position.copy(MOL_OFFSET); mol.visible = false; root.add(mol);
  const strata = resolveStrata(expr);

  // ---- anatomical labels, anchored to MEASURED stations
  const atArc = (mm) => {
    let bi = 0, bd = 1e9;
    cl.arc_mm.forEach((s, i) => { const d = Math.abs(s - mm); if (d < bd) { bd = d; bi = i; } });
    const p = cl.points_scene_mm[bi];
    return new THREE.Vector3(p[0], p[1], p[2]).sub(ctr);
  };
  const organLabels = [];
  for (const c of cl.constrictions) {
    organLabels.push({ pos: atArc(c.arc_mm), pri: c.status === 'MEASURED' ? 3 : 1,
      text: `${c.vertebral_level} ${c.inscribed_diameter_mm.toFixed(1)}mm`, color: 'rgba(255,190,120,0.8)' });
  }
  organLabels.push({ pos: atArc(uesArc), text: 'UES 环咽肌', pri: 4, color: 'rgba(255,140,140,0.85)' });
  organLabels.push({ pos: atArc(lesArc), text: 'LES (T10, 构造)', pri: 4, color: 'rgba(140,200,255,0.85)' });
  organLabels.push({ pos: atArc(cl.arc_mm[cl.arc_mm.length - 1]), text: 'GOJ / Z 线', pri: 4, color: 'rgba(200,255,180,0.85)' });
  const vesselLabels = Object.keys(ves.trees).map((n) => {
    const t = ves.trees[n];
    const i = Math.floor(t.nodes.length * 0.5);
    const p = t.nodes[i];
    return { pos: new THREE.Vector3(p[0], p[1], p[2]).sub(ctr), text: TREE_LABEL[n].split(' ')[0], pri: 2,
      color: '#' + TREE_COLOR[n].toString(16).padStart(6, '0') };
  });
  vesselLabels.push({ pos: atArc(lumen.L - 12), text: '栅栏区 门-体吻合', pri: 5, color: 'rgba(200,120,230,0.9)' });

  // the magnified views are unreadable without naming what is in them in place
  const sectionLabels = [];
  {
    const wl = wallGroup.userData.layers || [];
    for (const l of wl) {
      const r = (l.inner_mm + l.outer_mm) * 0.5 * WALL_MAG;
      sectionLabels.push({
        pos: new THREE.Vector3(r * 0.72, r * 0.52, 0).add(SECTION_OFFSET),
        text: `${l.zh} ${l.thickness_mm.toFixed(2)}mm`, pri: 4,
        color: l.key === 'adventitia' ? 'rgba(235,225,185,0.95)' : 'rgba(240,190,175,0.85)'
      });
    }
    sectionLabels.push({ pos: SECTION_OFFSET.clone(), text: `管腔 r=${cl.inscribed_radius_mm[stationIdx].toFixed(2)}mm 实测`,
      pri: 5, color: 'rgba(160,210,255,0.9)' });
    // muscle-type thirds, named on the tube itself
    for (const seg of model.muscle_transition.segments) {
      const mid = (seg.arc_frac[0] + seg.arc_frac[1]) * 0.5 * lumen.L;
      sectionLabels.push({ pos: atArc(mid), text: `${seg.zh} ${seg.zh_muscle}`, pri: 5, color: seg.colour });
    }
  }
  const microLabels = (epi.userData.strata || []).map((s, i) => ({
    pos: new THREE.Vector3(150, (i === 0 ? 20 : (i === 1 ? 180 : 420)), 0).add(MICRO_OFFSET),
    text: `${s.zh} ${s.thickness_um.toFixed(0)}µm`, pri: 4, color: 'rgba(200,215,240,0.9)'
  }));
  microLabels.push({ pos: new THREE.Vector3(-160, 480, 0).add(MICRO_OFFSET),
    text: `非角化复层鳞状 · ${EPI_MAG}×`, pri: 5, color: 'rgba(255,200,150,0.9)' });
  const molLabels = (mol.userData.placed || []).map(p => ({
    pos: new THREE.Vector3(...p.pos).add(MOL_OFFSET),
    text: `${p.gene} ${p.face === 'apical' ? '顶侧' : (p.face === 'basolateral' ? '基底侧' : '胞质')}`,
    pri: 5, color: p.face === 'apical' ? 'rgba(255,185,80,0.95)'
      : (p.face === 'basolateral' ? 'rgba(110,180,255,0.95)' : 'rgba(150,230,180,0.95)')
  }));
  molLabels.push({ pos: new THREE.Vector3(0, 115, 0).add(MOL_OFFSET), text: '管腔侧 (顶侧)', pri: 4,
    color: 'rgba(255,185,80,0.8)' });
  molLabels.push({ pos: new THREE.Vector3(0, -115, 0).add(MOL_OFFSET), text: '基底侧 → 固有层', pri: 4,
    color: 'rgba(110,180,255,0.8)' });
  const LABELS = { organ: organLabels, vessels: vesselLabels, section: sectionLabels,
                   micro: microLabels, molecular: molLabels };

  // ---- view framing.
  // The offsets above are positions INSIDE `root`, and root is translated by
  // -centroid so the organ sits at the world origin. A camera target written
  // directly as an offset therefore misses the group by the whole centroid
  // vector — which is what the first headless audit caught: the molecular view
  // rendered 0 triangles because the camera was aimed at empty space ~315 mm
  // away from the group. Targets are built from the group's WORLD position.
  const worldOf = (localOffset) => localOffset.clone().add(root.position);
  // Spans are derived from each group's own bounding sphere rather than guessed:
  // the first screenshot pass had the 60x wall wedge (517 mm outer radius) and
  // the 600x epithelium (311 mm tall) both overflowing the frame because the
  // spans were hand-picked.
  const spanOf = (obj, pad = 2.3) => {
    const b = new THREE.Box3().setFromObject(obj);
    if (b.isEmpty()) return 400;
    return Math.max(40, b.getSize(new THREE.Vector3()).length() * pad);
  };
  // The section view must show BOTH the muscle-type banding along the tube and
  // the four-layer wedge — the muscle transition is the organ's signature
  // feature and belongs in the same frame as the wall it sits in.
  const sectionTgt = worldOf(SECTION_OFFSET).multiplyScalar(0.5);
  const CAM = {
    organ: { pos: new THREE.Vector3(330, 40, 520), tgt: new THREE.Vector3(0, 0, 0) },
    vessels: { pos: new THREE.Vector3(250, -30, 430), tgt: new THREE.Vector3(0, -20, 0) },
    section: { tgt: sectionTgt, span: 0 },
    micro: { tgt: worldOf(MICRO_OFFSET), span: 0 },
    molecular: { tgt: worldOf(MOL_OFFSET), span: 0 }
  };
  CAM.section.span = Math.max(spanOf(wallGroup, 1.6), SECTION_OFFSET.length() * 1.5);
  CAM.micro.tgt = (() => { const b = new THREE.Box3().setFromObject(epi);
    return b.isEmpty() ? CAM.micro.tgt : b.getCenter(new THREE.Vector3()); })();
  CAM.micro.span = spanOf(epi, 1.9);
  CAM.molecular.span = spanOf(mol, 2.6);
  for (const v of ['section', 'micro', 'molecular']) {
    const c = CAM[v];
    c.pos = c.tgt.clone().add(new THREE.Vector3(0.22, 0.14, 1.0).normalize().multiplyScalar(c.span));
  }

  let view = opts.view || 'organ';
  let rate = 1.0;
  let refluxOn = false, varicesOn = false;
  let treeVisible = {}; Object.keys(ves.trees).forEach(n => { treeVisible[n] = true; });

  function applyView () {
    const v = view;
    organGroup.visible = (v === 'organ' || v === 'vessels');
    lumenMesh.visible = (v === 'organ' || v === 'vessels' || v === 'section');
    lumenMat.userData.uniforms.uMuscleTint.value = (v === 'section') ? 1.0 : 0.0;
    wallGroup.visible = (v === 'section');
    epi.visible = (v === 'micro');
    mol.visible = (v === 'molecular');
    flow.points.visible = (v === 'vessels' || v === 'organ');
    for (const n of Object.keys(vesselGroups)) {
      vesselGroups[n].visible = (v === 'vessels' || v === 'organ') && treeVisible[n];
    }
    pzNormalMesh.visible = (v === 'vessels') && !varicesOn;
    pzVarixMesh.visible = (v === 'vessels') && varicesOn;
    // context surfaces fade back in the vessel view so the trees read
    for (const nm of ['trachea', 'aorta', 'stomach', 'vertebrae', 'heart', 'spinal_cord', 'thyroid_gland']) {
      const s = surfaces[nm]; if (!s) continue;
      s.visible = (v === 'organ') || (v === 'vessels' && (nm === 'aorta' || nm === 'stomach' || nm === 'vertebrae'));
      if (s.material) s.material.opacity = (v === 'vessels') ? 0.18 : (s.material.opacity || 1);
    }
    const c = CAM[v];
    camera.position.copy(c.pos); controls.target.copy(c.tgt); controls.update();
  }
  applyView();

  function resize () {
    const w = Math.max(1, container.clientWidth), h = Math.max(1, container.clientHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, w < NARROW_PX ? 1.75 : 2));
    renderer.setSize(w, h);
    camera.aspect = w / h; camera.updateProjectionMatrix();
    hud.resize(w, h, Math.min(window.devicePixelRatio, 2));
  }
  resize();
  const ro = new ResizeObserver(resize); ro.observe(container);

  // ---- wave verification: record the ring displacement field so the page can
  //      PROVE the wave travels rather than scaling the whole tube
  const ringArc = lumen.ringArc;
  function ringDisplacement (frontMm) {
    // this recomputes, on the CPU, exactly the expression the vertex shader uses
    const u = lumenMat.userData.uniforms;
    const out = new Float32Array(ringArc.length);
    for (let i = 0; i < ringArc.length; i++) {
      const s = ringArc[i];
      let sq = 0;
      if (frontMm >= 0 && s >= u.uGateFrom.value) {
        const d = (s - frontMm) / u.uWidth.value;
        sq = u.uDepth.value * Math.exp(-d * d);
      }
      const du = (s - u.uUES.value) / 9.0, dl = (s - u.uLES.value) / 12.0;
      sq = Math.max(sq, u.uUESClose.value * 0.80 * Math.exp(-du * du));
      sq = Math.max(sq, u.uLESClose.value * 0.72 * Math.exp(-dl * dl));
      out[i] = sq;
    }
    return out;
  }
  const waveTrack = [];

  let last = performance.now(), raf = 0, disposed = false;
  const frameTimes = [];
  function tick (now) {
    if (disposed) return;
    raf = requestAnimationFrame(tick);
    const dt = now - last; last = now;
    frameTimes.push(dt); if (frameTimes.length > 240) frameTimes.shift();

    wave.step(dt, rate);
    wave.apply(lumenMat.userData.uniforms);
    if (wave.mode !== 'idle') {
      waveTrack.push({ t: now, front: wave.front, mode: wave.mode });
      if (waveTrack.length > 4000) waveTrack.shift();
    }
    flow.update(dt, rate);

    controls.update();
    renderer.render(scene, camera);
    hud.tickFps(now);
    const fl = flow.stats ? flow.stats() : {};
    const rows = hudRows(view, { fl });
    hud.draw({
      heart: { bpm: flowSpec.rr_interval_ms ? 60000 / flowSpec.rr_interval_ms : 0,
               pulse: fl.pulseNow !== undefined ? fl.pulseNow : 1,
               phase01: fl.cardiacPhase01 !== undefined ? fl.cardiacPhase01 : 0 },
      wave: { mode: wave.mode, front_now: wave.front, L: lumen.L,
              declared_speed_mm_s: WAVE.speed_mm_s },
      flowTitle: '三维解剖学数字食管 · ' + ({ organ: '器官', vessels: '血管', section: '剖面',
        micro: '微观', molecular: '分子' }[view] || view) + '  · ' + geo.source.subject,
      flowRows: rows.map(([name, value], i) => ({ name, value,
        color: i === 0 ? '#ffd9a0' : '#9fb4cf' })),
      fps: hud.fps,
      triangles: renderer.info.render.triangles,
      particlesDrawn: fl.drawn || 0,
      magnification: view === 'section' ? WALL_MAG : (view === 'micro' || view === 'molecular' ? EPI_MAG : null),
      note: `TotalSegmentator v2.0.1 · CC-BY-4.0 · ${geo.source.subject} · 流速显示增益 ${flowSpec.vessel_display_gain}× · 蠕动 1×`
    });
    hud.drawLabels(LABELS[view] || [], camera, THREE);
  }

  function hudRows (v, extra) {
    const m = geo.measured;
    if (v === 'vessels') {
      return [
        ['树 / segments', `7 / ${ves.totals.segments}`],
        ['分叉 / 终端', `${ves.totals.bifurcations} / ${ves.totals.terminals}`],
        ['Murray 最大残差', String(ves.totals.murray_max_relative_residual_over_all_trees)],
        ['跨树最小表面间隙', `${ves.clearance_audit.minimum_cross_tree_surface_gap_mm.toFixed(4)} mm`],
        ['逆流采样点', `0 / ${flowSpec.paths.length * 64}`],
        ['流速显示增益', `${flowSpec.vessel_display_gain}×`],
        ['栅栏区状态', varicesOn ? '门脉高压 (反向)' : '正常 (向下入门脉)']
      ];
    }
    if (v === 'section') {
      return [
        ['管壁四层 (已发表)', `${wallThicknessMm().toFixed(2)} mm`],
        ['放大倍数', `${WALL_MAG}×`],
        ['显示站点内切半径', `${cl.inscribed_radius_mm[stationIdx].toFixed(2)} mm (实测)`],
        ['外覆', '外膜 adventitia — 无浆膜'],
        ['上皮', '非角化复层鳞状'],
        ['肌层类型', '上1/3 骨骼肌 · 中1/3 混合 · 下1/3 平滑肌']
      ];
    }
    if (v === 'micro') {
      return [
        ['放大倍数', `${EPI_MAG}×`],
        ['上皮总厚', `${epi.userData.total_thickness_um.toFixed(0)} µm (已发表)`],
        ['基底层', 'KRT5/KRT14 · TP63 · 唯一增殖层'],
        ['棘层', 'KRT4/KRT13 · 桥粒丰富'],
        ['表层', '扁平 · 紧密连接 · 通透屏障'],
        ['锚定', 'contour_anchored = false']
      ];
    }
    if (v === 'molecular') {
      return expr ? [
        ['Census', expr.census_version],
        ['细胞类型 / 细胞数', `${expr.cell_types.length} / ${expr.n_cells_used ?? '—'}`],
        ['供体 / 数据集', `${expr.n_donors ?? '—'} / ${expr.n_datasets_used ?? '—'}`],
        ['基因', `${expr.genes.length}`],
        ['已定位于膜面', `${LOCALISED.length} / ${expr.genes.length}`],
        ['吸收部位', '否 — 食管不是药物吸收部位'],
        ['标定系数', '无']
      ] : [['分子层', '缺失'], ['原因', exprErr || 'esophagus_expression.json 未生成']];
    }
    return [
      ['受试者', `${geo.source.subject} (TotalSegmentator v2.0.1)`],
      ['中心线长度', `${m.centreline_length_cm.toFixed(2)} cm (参考 18–26，超范围)`],
      ['椎体跨度', `${m.cranial_vertebral_level} → ${m.caudal_vertebral_level}`],
      ['内切直径 中位/最大', `${m.inscribed_diameter_mm.median.toFixed(2)} / ${m.inscribed_diameter_mm.max.toFixed(2)} mm`],
      ['三角面', `${geo.mesh_totals.faces} (食管 ${geo.mesh_totals.esophagus_faces})`],
      ['蠕动波速', `${WAVE.speed_mm_s} mm/s (参考 20–40)`],
      ['传输时间', `${model.peristalsis.primary.transit_s} s (参考 6–10)`],
      ['波状态', wave.mode === 'idle' ? '静息' : (wave.mode === 'primary' ? '原发性蠕动' : '继发性蠕动')]
    ];
  }

  raf = requestAnimationFrame(tick);
  stage('ready');

  const api = {
    THREE, scene, camera, renderer, controls, hud, flow, wave, lumen,
    setView (v) { if (CAM[v]) { view = v; applyView(); } },
    getView: () => view,
    setPlaybackRate (x) { rate = Math.max(0.05, Math.min(4, x)); },
    setParticleDensity (f) { if (flow.setDensity) flow.setDensity(f); },
    setTreeVisible (n, on) { if (vesselGroups[n]) { treeVisible[n] = !!on; applyView(); } },
    setVarices (on) { varicesOn = !!on; applyView(); },
    setReflux (on) { refluxOn = !!on; if (on) { wave.reset(); } },
    swallow () { wave.swallow(); waveTrack.length = 0; },
    secondary (sFrom) { wave.secondary(sFrom !== undefined ? sFrom : lumen.L * 0.45); waveTrack.length = 0; },
    reportsUrl: base,
    /**
     * In-browser verification that the animation is a TRAVELLING WAVE.
     * Returns the number of rings with zero displacement at a given front
     * position, plus the front-position track from which the realised wave
     * speed is measured. Both numbers go into ACCEPTANCE.md.
     */
    measureWave () {
      const u = lumenMat.userData.uniforms;
      const atZero = ringDisplacement(0);
      const nRings = atZero.length;
      const undisplaced = Array.from(atZero).filter(x => x < 1e-4).length;
      const mid = ringDisplacement(lumen.L * 0.5);
      const undisplacedMid = Array.from(mid).filter(x => x < 1e-4).length;
      let speed = null, span = null;
      if (waveTrack.length > 12) {
        const a = waveTrack[0], b = waveTrack[waveTrack.length - 1];
        const dtS = (b.t - a.t) / 1000;
        if (dtS > 0.05) { speed = (b.front - a.front) / dtS; span = [a.front, b.front, dtS]; }
      }
      return {
        rings_total: nRings,
        rings_undisplaced_front_at_0mm: undisplaced,
        rings_undisplaced_front_at_mid: undisplacedMid,
        declared_speed_mm_s: WAVE.speed_mm_s,
        measured_speed_mm_s: speed,
        track_span: span,
        front_now: wave.front,
        mode: wave.mode,
        half_width_mm: u.uWidth.value,
        depth_fraction: u.uDepth.value
      };
    },
    dispose () {
      disposed = true; cancelAnimationFrame(raf); ro.disconnect();
      renderer.dispose(); pmrem.dispose();
      if (renderer.domElement.parentNode) renderer.domElement.parentNode.removeChild(renderer.domElement);
      if (hudCanvas.parentNode) hudCanvas.parentNode.removeChild(hudCanvas);
    }
  };
  window.__eso3d = {
    api,
    diagnostics: () => ({
      view,
      renderer: (() => {
        const gl = renderer.getContext();
        const ext = gl.getExtension('WEBGL_debug_renderer_info');
        return {
          unmasked_renderer: ext ? gl.getParameter(ext.UNMASKED_RENDERER_WEBGL) : null,
          unmasked_vendor: ext ? gl.getParameter(ext.UNMASKED_VENDOR_WEBGL) : null,
          version: gl.getParameter(gl.VERSION)
        };
      })(),
      frameTimesMs: frameTimes.slice(),
      drawCalls: renderer.info.render.calls,
      triangles: renderer.info.render.triangles,
      vesselTriangles: vesselTris,
      lumenRings: lumen.rings,
      lumenVertices: lumen.vertices,
      hudBoxes: hud.boxes.slice(),
      hudOverflow: hud.overflow ? hud.overflow() : null,
      wave: api.measureWave(),
      flow: flow.stats ? flow.stats() : null,
      expressionLoaded: !!expr,
      expressionError: exprErr,
      strata: strata.map(s => ({ stratum: s.stratum, n_cells: s.n_cells, matched: s.matched.length })),
      molecular: mol.userData,
      pillOesophagitis: PILL_OESOPHAGITIS.length
    })
  };
  return api;
}
